CREATE OR REPLACE FUNCTION public.library_recognition_fail(a uuid, did uuid, kind text, pos integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE u library_recognition_units;
BEGIN
